diagrams.032ec2b9c26d:
classDiagram
    direction TB
    class Notebook {
        +String name
        +add(note Note)
        +search(query String) List~Note~
    }
    class Note {
        +String title
        -String body
        +Date updatedAt
        +save() bool
    }
    class Version {
        +Date savedAt
        +String body
    }
    class Tag {
        +String name
    }
    class Exporter {
        <<interface>>
        +export(note Note) File
    }
    class PdfExporter
    class HtmlExporter
    Notebook "1" *-- "*" Note : owns
    Note "1" *-- "*" Version : keeps
    Note "*" o-- "*" Tag : tagged with
    Exporter <|.. PdfExporter
    Exporter <|.. HtmlExporter
    PdfExporter ..> Note : reads
    HtmlExporter ..> Note : reads

